CREATE TABLE IF NOT EXISTS schema_versions(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id bigserial PRIMARY KEY, name varchar(80) NOT NULL, email varchar(254) NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL DEFAULT 'cliente' CHECK(role IN ('cliente','administrador')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS auth_attempts(id bigserial PRIMARY KEY, fingerprint text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS auth_attempts_lookup ON auth_attempts(fingerprint,created_at);
CREATE TABLE IF NOT EXISTS categories(id bigserial PRIMARY KEY, nombre varchar(80) NOT NULL, normalized text NOT NULL UNIQUE, slug text NOT NULL UNIQUE, descripcion text, orden integer NOT NULL DEFAULT 0 CHECK(orden>=0), estado text NOT NULL CHECK(estado IN ('activo','inactivo')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS colors(id bigserial PRIMARY KEY, nombre varchar(40) NOT NULL, normalized text NOT NULL UNIQUE, tono varchar(7) NOT NULL);
CREATE TABLE IF NOT EXISTS products(id bigserial PRIMARY KEY, nombre varchar(150) NOT NULL, slug text NOT NULL UNIQUE, descripcion text, precio numeric(8,2) NOT NULL CHECK(precio>0), sku varchar(50) NOT NULL UNIQUE, categoria_id bigint NOT NULL REFERENCES categories(id), color_id bigint REFERENCES colors(id), existencias integer NOT NULL CHECK(existencias>=0), imagenes jsonb NOT NULL DEFAULT '[]', estado text NOT NULL CHECK(estado IN ('activo','inactivo')), deleted boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS collections(id bigserial PRIMARY KEY, nombre varchar(100) NOT NULL, normalized text NOT NULL UNIQUE, slug text NOT NULL UNIQUE, descripcion text, imagen_portada_url text, estado text NOT NULL CHECK(estado IN ('activo','inactivo')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS collection_products(collection_id bigint NOT NULL REFERENCES collections(id) ON DELETE CASCADE, product_id bigint NOT NULL REFERENCES products(id), PRIMARY KEY(collection_id,product_id));
CREATE TABLE IF NOT EXISTS stock_movements(id bigserial PRIMARY KEY, product_id bigint NOT NULL REFERENCES products(id), user_id bigint NOT NULL REFERENCES users(id), before_qty integer NOT NULL, after_qty integer NOT NULL CHECK(after_qty>=0), reason varchar(200) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders(id bigserial PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), idempotency_key varchar(100) NOT NULL, request_hash text NOT NULL, subtotal numeric(10,2) NOT NULL, discount numeric(10,2) NOT NULL, shipping numeric(10,2) NOT NULL, total numeric(10,2) NOT NULL, delivery text NOT NULL, payment text NOT NULL DEFAULT 'transferencia', payment_status text NOT NULL DEFAULT 'pendiente' CHECK(payment_status IN ('pendiente','confirmado')), status text NOT NULL DEFAULT 'pendiente', gift boolean NOT NULL DEFAULT false, address jsonb NOT NULL DEFAULT '{}', carrier varchar(80), tracking varchar(100), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,idempotency_key));
CREATE TABLE IF NOT EXISTS order_items(id bigserial PRIMARY KEY, order_id bigint NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id bigint NOT NULL REFERENCES products(id), nombre text NOT NULL, sku text NOT NULL, color text, quantity integer NOT NULL CHECK(quantity>0), price numeric(8,2) NOT NULL, UNIQUE(order_id,product_id));
CREATE TABLE IF NOT EXISTS order_events(id bigserial PRIMARY KEY, order_id bigint NOT NULL REFERENCES orders(id), user_id bigint NOT NULL REFERENCES users(id), action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews(id bigserial PRIMARY KEY, product_id bigint NOT NULL REFERENCES products(id), user_id bigint NOT NULL REFERENCES users(id), rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), comment varchar(1000) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(product_id,user_id));
CREATE TABLE IF NOT EXISTS returns(id bigserial PRIMARY KEY, order_id bigint NOT NULL REFERENCES orders(id), product_id bigint NOT NULL REFERENCES products(id), user_id bigint NOT NULL REFERENCES users(id), reason varchar(80) NOT NULL, comment varchar(1000) NOT NULL, status text NOT NULL DEFAULT 'Solicitada' CHECK(status IN ('Solicitada','En revisión','Resuelta','Rechazada')), created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS returns_open ON returns(order_id,product_id) WHERE status IN ('Solicitada','En revisión');
INSERT INTO schema_versions(version) VALUES(1) ON CONFLICT DO NOTHING;
